SELECT EMP1.EMPNO, CASE WHEN t6.c = 0 THEN FALSE WHEN EMP1.DEPTNO IS NULL THEN NULL WHEN t11.i IS NOT NULL THEN TRUE WHEN t6.ck < t6.c THEN NULL ELSE FALSE END AS D FROM EMP AS EMP1 CROSS JOIN (SELECT COUNT(*) AS c, COUNT(DEPTNO) AS ck FROM (SELECT EMPNO, DEPTNO FROM EMP) AS t3 WHERE EMPNO < 20) AS t6 LEFT JOIN (SELECT t8.DEPTNO, TRUE AS i FROM (SELECT * FROM (SELECT EMPNO, DEPTNO FROM EMP) AS t7 WHERE EMPNO < 20) AS t8 GROUP BY t8.DEPTNO) AS t11 ON EMP1.DEPTNO = t11.DEPTNO
